INSERT INTO auth_refresh_session (
    user_id, tenant_id, token_hash, family_id, previous_session_id,
    status, expires_at, revoked_at
) VALUES (
    #{userId}, #{tenantId}, #{tokenHash}, #{familyId}, #{previousSessionId},
    #{status}, #{expiresAt}, #{revokedAt}
)

mapper.update:
UPDATE auth_refresh_session
SET status = 'ROTATED', updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'ACTIVE'

UPDATE auth_refresh_session
SET status = 'EXPIRED', updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'ACTIVE'

UPDATE auth_refresh_session
SET status = 'REVOKED', revoked_at = #{revokedAt}, updated_at = #{revokedAt}
WHERE family_id = #{familyId}
  AND status IN ('ACTIVE', 'ROTATED')
